/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */
[web]
{
parm(in:&Mode, in:&prefCodigo, in:&AtendimentoCodigo);

prefCodigo = &prefCodigo if not &prefCodigo.IsEmpty();
noaccept(prefCodigo) if not &prefCodigo.IsEmpty();
AtendimentoCodigo = &AtendimentoCodigo if not &AtendimentoCodigo.IsEmpty();
noaccept(AtendimentoCodigo) if not &AtendimentoCodigo.IsEmpty();

locCodigo = &Insert_locCodigo if &Mode = TrnMode.Insert and not &Insert_locCodigo.IsEmpty();
noaccept(locCodigo) if &Mode = TrnMode.Insert and not &Insert_locCodigo.IsEmpty();
AreEnsCodigo = &Insert_AreEnsCodigo if &Mode = TrnMode.Insert and not &Insert_AreEnsCodigo.IsEmpty();
noaccept(AreEnsCodigo) if &Mode = TrnMode.Insert and not &Insert_AreEnsCodigo.IsEmpty();
AreEnsSequencial = &Insert_AreEnsSequencial if &Mode = TrnMode.Insert and not &Insert_AreEnsSequencial.IsEmpty();
noaccept(AreEnsSequencial) if &Mode = TrnMode.Insert and not &Insert_AreEnsSequencial.IsEmpty();
carGruCodigo = &Insert_carGruCodigo if &Mode = TrnMode.Insert and not &Insert_carGruCodigo.IsEmpty();
noaccept(carGruCodigo) if &Mode = TrnMode.Insert and not &Insert_carGruCodigo.IsEmpty();
AtendimentoCodigo.Visible = AtendimentoCodigo <> 0;
AtendimentoCodigo_Cell.Class = !'Invisible' If not(AtendimentoCodigo <> 0);
AtendimentoCodigo_Cell.Class = !'col-xs-12 DataContentCell' If AtendimentoCodigo <> 0;
locCodigo = &CombolocCodigo;
}

prefCodigo = &WWPContext.prefCodigo;
/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

Default(AtendimentoStatus,Status.Ativo);

AtendimentoDataCadastro = ServerNow() 
	on beforeInsert;

AtendimentoDataAlteracao = ServerNow() 
	on beforeUpdate;

AtendimentoCodigo = PRCDGerarNovoCodigo(!'atendimento')
	on BeforeInsert;

Event Start

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

	//Code block: EditFormClass
	[web]{
		LayoutMainTable.Class = LayoutMainTable.Class + " " + ThemeClass:EditForm
	}

	LoadWWPContext.Call(&WWPContext)

	[web]
	{
	locCodigo.Visible = False
	&CombolocCodigo.SetEmpty()
	&CombolocCodigo.Visible = False
	Do 'LoadCombolocCodigo'
	}
	Do 'AttributesSecurityCode'

	&TrnContext.FromXml(&WebSession.Get(!"TrnContext"))
	If (&TrnContext.TransactionName = &Pgmname and &Mode = TrnMode.Insert)
		For &TrnContextAtt in &TrnContext.Attributes
			Do Case
				// When inserting with instantiated locCodigo
				Case &TrnContextAtt.AttributeName = !"locCodigo"
					&Insert_locCodigo.FromString(&TrnContextAtt.AttributeValue)
					[web]
					{
					If not &Insert_locCodigo.IsEmpty()
						&CombolocCodigo = &Insert_locCodigo
						Combo_locCodigo.SelectedValue_set = &CombolocCodigo.ToString().Trim()
						Combo_locCodigo.Enabled = False
					EndIf
					}
				// When inserting with instantiated AreEnsCodigo
				Case &TrnContextAtt.AttributeName = !"AreEnsCodigo"
					&Insert_AreEnsCodigo.FromString(&TrnContextAtt.AttributeValue)
				// When inserting with instantiated AreEnsSequencial
				Case &TrnContextAtt.AttributeName = !"AreEnsSequencial"
					&Insert_AreEnsSequencial.FromString(&TrnContextAtt.AttributeValue)
				// When inserting with instantiated carGruCodigo
				Case &TrnContextAtt.AttributeName = !"carGruCodigo"
					&Insert_carGruCodigo.FromString(&TrnContextAtt.AttributeValue)
			Endcase
		Endfor
	Endif

    [web]
    {
	prefCodigo.Visible = False
	AtendimentoDataCadastro.Visible = False
	AtendimentoDataAlteracao.Visible = False
	AreEnsEtapaNivel.Visible = False
	AreEnsEtapaNumero.Visible = False
	prefMunCod.Visible = False
	carGruQtdeItens.Visible = False
	carDapMesAno.Visible = False
	}

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

EndEvent

Event After Trn

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

   [web]
   {

	If (&Mode = TrnMode.Delete and not &TrnContext.CallerOnDelete)
		AtendimentoWW.Call()
	Endif

	Return
   }

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

EndEvent

Sub 'AttributesSecurityCode'

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

[web]
{
	AtendimentoCodigo.Visible = False
	AtendimentoCodigo_Cell.Class = !'Invisible'

}

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

EndSub

[web]
{

Event Combo_locCodigo.OnOptionClicked

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

	&CombolocCodigo.FromString(Combo_locCodigo.SelectedValue_get)

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

EndEvent

Sub 'LoadCombolocCodigo'

	/* Generated by DVelop Work With Plus Pattern [Start] - Do not change */

	&locCodigo_Data = AtendimentoLoadDVCombo(!'locCodigo', &Mode, &prefCodigo, &AtendimentoCodigo, &ComboSelectedValue)
	Combo_locCodigo.SelectedValue_set = &ComboSelectedValue
	&CombolocCodigo.FromString(&ComboSelectedValue)
	If &Mode = TrnMode.Display OR &Mode = TrnMode.Delete
		Combo_locCodigo.Enabled = False
	EndIf

	/* Generated by DVelop Work With Plus Pattern [End] - Do not change */

EndSub

}
